import { useState } from "react";

export function RightClickMenu({
  itemLabel = "{{itemLabel}}",
  open: initialOpen = {{open}},
  accent = "{{accent}}",
}) {
  const [open, setOpen] = useState(initialOpen);
  const rowStyle = { display: "block", width: "100%", boxSizing: "border-box", textAlign: "left", padding: "8px 10px", border: "none", background: "transparent", borderRadius: 6, cursor: "pointer" };
  return (
    <div style={{ width: 260, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", position: "relative" }}>
      <div onContextMenu={(e) => { e.preventDefault(); setOpen(true); }} style={{ padding: "10px 12px", borderRadius: 8, background: "#24143010", width: "fit-content" }}>&#128196; {itemLabel}</div>
      {open && (
        <div style={{ position: "relative", marginTop: 8, width: 160, borderRadius: 10, background: "#FAF7F2", boxShadow: "0 12px 26px rgba(36,20,48,.2)", border: "1.5px solid #24143014", padding: 6 }}>
          <div style={{ position: "absolute", top: -14, left: -6, fontSize: 16, color: accent }}>&#8598;</div>
          <button type="button" style={rowStyle}>Rename</button>
          <button type="button" style={rowStyle}>Duplicate</button>
          <button type="button" style={{ ...rowStyle, color: "#b3261e" }}>Delete</button>
        </div>
      )}
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430aa" }}>{open ? "right-click (or long-press on touch) opens the context menu" : "rest state"}</p>
    </div>
  );
}
